"""C5 calibration report writer.

Writes eval_corpus/calibration_report.md and updates the threshold constants
in src/ingestion/structurer.py between the calibrate:start / calibrate:end markers.
"""

from __future__ import annotations

import re
from datetime import UTC, datetime
from pathlib import Path

from src.eval.calibration.grid_search import (
    AA_RECALL_MIN,
    REVIEW_PRECISION_MIN,
    THRESHOLDS_AUTO_ACCEPT,
    THRESHOLDS_REJECT,
    GridCell,
)

_MARKER_START = "# >>> calibrate:start"
_MARKER_END = "# >>> calibrate:end"

_CONSTANTS_TEMPLATE = (
    "{start} — generated by calibrate; do not edit by hand\n"
    "THRESHOLD_AUTO_ACCEPT: float = {ta:.1f}\n"
    "THRESHOLD_REJECT: float = {tr:.1f}\n"
    "{end}"
)


def write_report(
    cells: list[GridCell],
    best: GridCell | None,
    out_path: Path,
) -> None:
    """Write the full calibration report to out_path."""
    lines: list[str] = [
        "# Calibration Report",
        "",
        f"**Generated:** {datetime.now(UTC).strftime('%Y-%m-%dT%H:%M:%SZ')}",
        "",
        "## Definitions",
        "",
        "- **auto-accept precision**: of records routed to auto-accept, "
        "fraction with correct value",
        "- **auto-accept recall**: of all correct records in corpus, "
        "fraction that landed in auto-accept",
        "- **review precision**: of records routed to review band, fraction with correct value",
        '- **"correct"**: matched candidate whose extracted value matches GT '
        "within ±0.5% (decimal) or exact (integer)",
        "",
        "## Selection rule",
        "",
        f"Maximise auto-accept precision subject to aa_recall ≥ {AA_RECALL_MIN} "
        f"AND review_precision ≥ {REVIEW_PRECISION_MIN}.",
        "If no cell qualifies, fall back to (95.0, 70.0) and emit CALIBRATION FAILED.",
        "",
        "## Grid (aa_prec / aa_recall / review_prec)",
        "",
    ]

    # Build grid table — rows = THRESHOLD_AUTO_ACCEPT, cols = THRESHOLD_REJECT
    header = "| ta \\ tr |" + "".join(f" {tr:.0f} |" for tr in THRESHOLDS_REJECT)
    sep = "|---|" + "---|" * len(THRESHOLDS_REJECT)
    lines += [header, sep]

    cell_map: dict[tuple[float, float], GridCell] = {
        (c.threshold_auto_accept, c.threshold_reject): c for c in cells
    }

    for ta in THRESHOLDS_AUTO_ACCEPT:
        row = f"| **{ta:.0f}** |"
        for tr in THRESHOLDS_REJECT:
            c = cell_map[(ta, tr)]
            marker = " ★" if (best and c is best) else ""
            row += f" {c.aa_precision:.3f} / {c.aa_recall:.3f} / {c.review_precision:.3f}{marker} |"
        lines.append(row)

    lines += [""]

    if best:
        lines += [
            "## Chosen pair",
            "",
            f"- **THRESHOLD_AUTO_ACCEPT = {best.threshold_auto_accept:.1f}**",
            f"- **THRESHOLD_REJECT = {best.threshold_reject:.1f}**",
            f"- aa_precision = {best.aa_precision:.4f}",
            f"- aa_recall = {best.aa_recall:.4f}",
            f"- review_precision = {best.review_precision:.4f}",
            "",
            "## Per-band counts (chosen pair)",
            "",
            "| Band | Total candidates |",
            "|---|---|",
            f"| auto_accept | {best.aa_total} |",
            f"| review | {best.review_total} |",
            f"| reject | {best.reject_total} |",
            "",
        ]
    else:
        lines += [
            "## ⚠ CALIBRATION FAILED",
            "",
            f"No grid cell satisfied aa_recall ≥ {AA_RECALL_MIN}"
            f" AND review_precision ≥ {REVIEW_PRECISION_MIN}.",
            "Falling back to initial constants (95.0, 70.0).",
            "Investigate corpus quality or widen the selection rule before the demo.",
            "",
        ]

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines))


def write_constants(ta: float, tr: float, structurer_path: Path) -> None:
    """Replace threshold constants between calibrate markers in structurer.py."""
    text = structurer_path.read_text()
    pattern = re.compile(
        rf"({re.escape(_MARKER_START)}).*?({re.escape(_MARKER_END)})",
        re.DOTALL,
    )
    replacement = _CONSTANTS_TEMPLATE.format(
        start=_MARKER_START,
        end=_MARKER_END,
        ta=ta,
        tr=tr,
    )
    new_text, count = pattern.subn(replacement, text)
    if count != 1:
        raise ValueError(
            f"Expected exactly one calibrate marker block in {structurer_path} "
            f"(found {count}). Expected '{_MARKER_START}' ... '{_MARKER_END}'."
        )
    structurer_path.write_text(new_text)
